import numpy as np
import geopandas as gpd
from shapely.geometry import Point

def task_func(dic={'Lon': (-180, 180), 'Lat': (-90, 90)}, cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney']):
    # Check for missing keys
    missing_keys = []
    if 'Lon' not in dic:
        missing_keys.append('Lon')
    if 'Lat' not in dic:
        missing_keys.append('Lat')

    if missing_keys:
        if len(missing_keys) == 2:
            raise ValueError("Missing required keys: 'Lon' and 'Lat'")
        else:
            raise ValueError(f"Missing required key: '{missing_keys[0]}'")

    # Generate random coordinates for each city
    lon_range = dic['Lon']
    lat_range = dic['Lat']

    coordinates = []
    for _ in cities:
        lon = np.random.uniform(lon_range[0], lon_range[1])
        lat = np.random.uniform(lat_range[0], lat_range[1])
        coordinates.append(Point(lon, lat))

    # Create GeoDataFrame
    gdf = gpd.GeoDataFrame({
        'City': cities,
        'Coordinates': coordinates
    }, geometry='Coordinates')

    return gdf

import numpy as np
import geopandas as gpd
from shapely.geometry import Point

def task_func(dic={'Lon': (-180, 180), 'Lat': (-90, 90)}, cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney']):
    # Check for missing keys
    missing_keys = []
    if 'Lon' not in dic:
        missing_keys.append('Lon')
    if 'Lat' not in dic:
        missing_keys.append('Lat')

    if missing_keys:
        if len(missing_keys) == 2:
            raise ValueError("Missing required keys: 'Lon' and 'Lat'")
        else:
            raise ValueError(f"Missing required key: '{missing_keys[0]}'")

    # Check if values are tuples
    if not isinstance(dic['Lon'], tuple) or not isinstance(dic['Lat'], tuple):
        raise ValueError("'Lon' and 'Lat' keys in the dictionary are not tuples.")

    # Generate random coordinates
    np.random.seed(42)
    lon_min, lon_max = dic['Lon']
    lat_min, lat_max = dic['Lat']

    coordinates = []
    for _ in cities:
        lon = np.random.uniform(lon_min, lon_max)
        lat = np.random.uniform(lat_min, lat_max)
        coordinates.append(Point(lon, lat))

    # Create GeoDataFrame
    gdf = gpd.GeoDataFrame({
        'City': cities,
        'Coordinates': coordinates
    }, geometry='Coordinates')

    return gdf
